// Script: add EN translations to data.js nodes
// Run from: PAGINA WEB/web/
// Usage: node add_en_translations.js

const fs = require('fs');
const path = require('path');

const filePath = path.join(__dirname, 'data.js');
const content = fs.readFileSync(filePath, 'utf8');

// Extract the JSON object from  window.RDC_DATA = {...};
const match = content.match(/^window\.RDC_DATA\s*=\s*([\s\S]+?);\s*$/m);
if (!match) {
  // Try without strict line anchors
  const i = content.indexOf('{');
  const j = content.lastIndexOf('}');
  if (i < 0 || j < 0) { console.error('Cannot parse data.js'); process.exit(1); }
  var jsonStr = content.slice(i, j + 1);
} else {
  var jsonStr = match[1];
}

const data = JSON.parse(jsonStr);

